package com.zheng.algorithm.leetcode.medium;

import java.util.ArrayList;
import java.util.List;

/**
 * @author zheng
 * @date 2020/11/19
 */
public class LeetCode105 {

    public static void main(String[] args) {
        LeetCode105 leetCode105 = new LeetCode105();
        int[] preorder = {3, 9, 20, 15, 7};
        int[] inorder = {9, 3, 15, 20, 7};
        leetCode105.buildTree(preorder, inorder);
    }

    public TreeNode buildTree(int[] preorder, int[] inorder) {
        if (preorder == null || inorder == null) {
            return null;
        }
        List&lt;Integer&gt; list = new ArrayList&lt;&gt;();
        for (int i : inorder) {
            list.add(i);
        }
        return buildTree(preorder, 0, preorder.length - 1, list, 0, inorder.length - 1);
    }

    private TreeNode buildTree(int[] preorder, int preLeft, int preRight, List&lt;Integer&gt; inorder, int inLeft, int inRight) {
        if (preLeft &gt; preRight || inLeft &gt; inRight) {
            return null;
        }
        int rootValue = preorder[preLeft];
        TreeNode root = new TreeNode(rootValue);
        int index = inorder.indexOf(rootValue);
        int leftSize = index - inLeft;
        root.left = buildTree(preorder, preLeft + 1, preLeft + leftSize, inorder, inLeft, index - 1);
        root.right = buildTree(preorder, preLeft + leftSize + 1, preRight, inorder, index + 1, inRight);
        return root;
    }

    static class TreeNode {
        int val;
        TreeNode left;
        TreeNode right;

        TreeNode(int x) {
            val = x;
        }
    }
}

